# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""Fused Triton implementation of aten::column_stack.out.

Semantics:
  * logical view of input j: rows R, columns C_j, shared tail shape
    (rank 0 -> (1,1), rank 1 -> (L,1), rank >= 2 -> as-is);
  * out is resized in place to (R, sum C_j) + tail and the SAME object is
    returned (resize only when the shape differs, like resize_output);
  * value path is a single conversion input dtype -> out dtype;
  * the cast gate is ATen canCast(promote(input, out), out);
  * empty tensor list / mismatched leading dims raise.

One fused launch writes the whole output.  The logical output plane is (R, K)
with K = sum(C_j) * prod(tail); program `pid` owns a BLOCK-element slice of one
input's column slab for one row, so each program issues one bulk load and one
bulk store.

Round-1 profiling showed the device copy is already at the reference streaming
rate and that essentially all of the gap is a byte-independent per-call cost
(launch side).  The hot path therefore avoids the generic JIT dispatch:
  * a single pre-validated launch plan (per-input dtype/shape/stride signature,
    output geometry, cached compiled-kernel launcher);
  * the kernel is relaunched the way JITFunction.run launches it (grid dims,
    stream, function, packed metadata, hooks, plus the constexpr slots the
    generated launcher parses) but without re-binding the arguments,
    recomputing the specialization cache key, or re-running the compile-option
    pass.
Every fast-path hit still re-reads the live tensors and re-validates the full
geometry; any mismatch falls back to the validating cold path, which builds a
fresh plan and launches normally.
"""

import torch
import triton
import triton.language as tl
from triton import knobs as _knobs
from triton.runtime import driver as _tdriver

# Pointer element type used for dtypes Triton cannot compute on; every mapping
# below is a zero-copy same-itemsize reinterpret, so copies stay bit-exact.
_EFF = {
    torch.bool: torch.uint8,
    torch.float64: torch.int64,
    torch.complex64: torch.int64,
}

_TL = {
    torch.uint8: tl.uint8,
    torch.int8: tl.int8,
    torch.int16: tl.int16,
    torch.int32: tl.int32,
    torch.int64: tl.int64,
    torch.float16: tl.float16,
    torch.bfloat16: tl.bfloat16,
    torch.float32: tl.float32,
}

_FLOAT = (torch.float16, torch.bfloat16, torch.float32, torch.float64)
_COMPLEX = (torch.complex64, torch.complex128)
_INT = (torch.uint8, torch.int8, torch.int16, torch.int32, torch.int64)

_SHORT = {
    torch.bool: "Bool",
    torch.uint8: "Byte",
    torch.int8: "Char",
    torch.int16: "Short",
    torch.int32: "Int",
    torch.int64: "Long",
    torch.float16: "Half",
    torch.bfloat16: "BFloat16",
    torch.float32: "Float",
    torch.float64: "Double",
    torch.complex64: "ComplexFloat",
    torch.complex128: "ComplexDouble",
}

_NMAX = 4
_NARGS = 5 + 3 + 4 * 4 + 1  # out + 4 ptrs, starts, off/span/sr/cs, K

# One pre-validated launch plan:
#   (n, signature, od, oshape, odev, args, launch, ptrs, int_mode)
_LAST = None
_INSTALL_ERROR = None
# Whether the hot path may pass raw integer data pointers; disabled for the
# rest of the process if the launcher ever rejects them.
_INT_PTRS = True


class _OutCastError(TypeError, RuntimeError):
    """Matches ATen's canCast rejection (TypeError) and tolerates RuntimeError."""


def _can_cast(src, dst):
    """aten::canCast."""
    if src is dst or src == dst:
        return True
    if src in _COMPLEX and dst not in _COMPLEX:
        return False
    if src in _FLOAT and dst in _INT:
        return False
    if src == torch.bool and (dst in _INT or dst in _COMPLEX):
        return False
    return True


@triton.jit
def _tile(
    out_ptr,
    ptr,
    off,
    span,
    sr,
    cs,
    row,
    pid,
    start,
    K,
    BLOCK: tl.constexpr,
    CONV: tl.constexpr,
    OD: tl.constexpr,
):
    # One bulk copy: `span` flat columns of one input's row into out's slab.
    offsets = (pid - start) * BLOCK + tl.arange(0, BLOCK)
    m = offsets < span
    v = tl.load(ptr + row * sr + offsets * cs, mask=m, other=0)
    if CONV:
        v = v.to(OD)
    tl.store(out_ptr + row * K + off + offsets, v, mask=m)


@triton.jit
def _column_stack_kernel(
    out_ptr,
    p0,
    p1,
    p2,
    p3,
    s1,
    s2,
    s3,
    o0,
    o1,
    o2,
    o3,
    n0,
    n1,
    n2,
    n3,
    sr0,
    sr1,
    sr2,
    sr3,
    cs0,
    cs1,
    cs2,
    cs3,
    K,
    BLOCK: tl.constexpr,
    NIN: tl.constexpr,
    CONV: tl.constexpr,
    OD: tl.constexpr,
    BR: tl.constexpr,
):
    pid = tl.program_id(0)
    # Small output planes are tiled BR rows per program so the launch stays a
    # few dozen programs instead of one program per row; large planes use BR=1,
    # which makes this loop a single unrolled iteration.
    row0 = tl.program_id(1) * BR
    for i in tl.static_range(BR):
        row = row0 + i
        if pid < s1:
            _tile(out_ptr, p0, o0, n0, sr0, cs0, row, pid, 0, K, BLOCK, CONV, OD)
        if NIN > 1:
            if pid >= s1:
                if pid < s2:
                    _tile(
                        out_ptr, p1, o1, n1, sr1, cs1, row, pid, s1, K, BLOCK, CONV, OD
                    )
        if NIN > 2:
            if pid >= s2:
                if pid < s3:
                    _tile(
                        out_ptr, p2, o2, n2, sr2, cs2, row, pid, s2, K, BLOCK, CONV, OD
                    )
        if NIN > 3:
            if pid >= s3:
                _tile(out_ptr, p3, o3, n3, sr3, cs3, row, pid, s3, K, BLOCK, CONV, OD)


def _make_launch(kernel, grid, dev):
    """Mirror JITFunction.run's launch call with a cached compiled kernel."""
    column_stack_out = (
        kernel.column_stack_out
    )  # initialises handles, returns the backend launcher
    fn = kernel.function
    packed = kernel.packed_metadata
    md = kernel.launch_metadata
    driver = _tdriver.active
    g0 = grid[0]
    g1 = grid[1] if len(grid) > 1 else 1
    g2 = grid[2] if len(grid) > 2 else 1
    rt = _knobs.runtime

    def launch(args):
        stream = driver.get_current_stream(dev)
        hook = rt.launch_enter_hook
        if hook is None:
            lm = None
        else:
            lm = md(grid, stream, *args)
        column_stack_out(
            g0, g1, g2, stream, fn, packed, lm, hook, rt.launch_exit_hook, *args
        )

    return launch


def _prepare(tensors):
    n = len(tensors)
    if n == 0:
        raise RuntimeError("column_stack expects a non-empty TensorList")

    rows = -1
    tail = ()
    cols = []
    for t in tensors:
        d = t.dim()
        if d == 0:
            r, c, tshape = 1, 1, ()
        elif d == 1:
            r, c, tshape = t.shape[0], 1, ()
        else:
            r, c, tshape = t.shape[0], t.shape[1], tuple(t.shape[2:])
        if rows < 0:
            rows, tail = r, tshape
        elif r != rows:
            raise RuntimeError(
                "Sizes of tensors must match except in dimension 1. Expected size "
                "%d but got size %d for tensor number %d in the list."
                % (rows, r, len(cols))
            )
        elif tshape != tail:
            raise RuntimeError(
                "Tensors must have same number of dimensions: got %d and %d"
                % (1 + len(tail), d)
            )
        cols.append(c)

    total = sum(cols)
    ntail = 1
    for v in tail:
        ntail *= v
    K = total * ntail
    out_shape = (rows, total) + tail
    return n, rows, tail, cols, total, ntail, K, out_shape


def _build(tensors, out):
    """Cold path: full validation, plan construction and one launch."""
    global _LAST, _INSTALL_ERROR
    od = out.dtype
    n, rows, tail, cols, total, ntail, K, out_shape = _prepare(tensors)

    for t in tensors:
        common = torch.promote_types(t.dtype, od)
        if not _can_cast(common, od):
            raise _OutCastError(
                "torch.cat(): input types can't be cast to the desired output "
                "type %s" % _SHORT.get(od, str(od))
            )

    if tuple(out.shape) != out_shape:
        out.resize_(out_shape)

    if rows == 0 or K == 0:
        return out

    eff_od = _EFF.get(od, od)
    geoms = []
    reusable = _EFF.get(od, None) is None
    off = 0
    for t, c in zip(tensors, cols):
        d = t.dim()
        if d == 0:
            sr, cs = 0, 1
        elif d == 1:
            sr, cs = t.stride(0), 1
        elif d == 2:
            sr, cs = t.stride(0), t.stride(1)
        else:
            sr, cs = t.stride(0), 1
            exp = 1
            ok = True
            for k in range(d - 1, 1, -1):
                if t.stride(k) != exp:
                    ok = False
                    break
                exp *= t.shape[k]
            if not ok or t.stride(1) != ntail:
                raise NotImplementedError(
                    "column_stack: unsupported non-contiguous tail layout"
                )
        if t.dtype != od:
            if eff_od != od or _EFF.get(t.dtype, t.dtype) != t.dtype:
                raise NotImplementedError(
                    "column_stack: unsupported conversion from %s to %s" % (t.dtype, od)
                )
        e = _EFF.get(t.dtype, None)
        if e is not None:
            reusable = False
            ptr = t.view(e)
        else:
            ptr = t
        geoms.append((ptr, off * ntail, c * ntail, sr, cs))
        off += c

    oe = _EFF.get(od, None)
    out_ptr = out if oe is None else out.view(oe)
    od_tl = _TL.get(eff_od)
    if od_tl is None:
        raise NotImplementedError("column_stack: unsupported output dtype %s" % od)
    conv = any(t.dtype != od for t in tensors)

    # Tile the widest slab at up to ~32 KiB, never wider than that slab.
    cap = 8192 if out.element_size() >= 4 else 16384
    target = max(g[2] for g in geoms)
    block = 32
    while block < target and block < cap:
        block *= 2

    if n > _NMAX:
        # More inputs than kernel pointer slots: one launch per input, each
        # still writing straight into its own column slab of out.
        for g in geoms:
            _launch_single(g, out_ptr, K, rows, block, conv, od_tl)
        return out

    starts = []
    acc = 0
    for g in geoms:
        starts.append(acc)
        acc += triton.cdiv(g[2], block) if g[2] > 0 else 0
    total_tiles = acc

    st = (starts + [acc] * 4)[:4]
    args = [out_ptr] + [None] * _NMAX
    args += [st[1], st[2], st[3]]
    args += [g[1] for g in geoms] + [0] * (_NMAX - len(geoms))
    args += [g[2] for g in geoms] + [0] * (_NMAX - len(geoms))
    args += [g[3] for g in geoms] + [0] * (_NMAX - len(geoms))
    args += [g[4] for g in geoms] + [0] * (_NMAX - len(geoms))
    args.append(K)
    assert len(args) == _NARGS

    for i in range(_NMAX):
        args[1 + i] = geoms[i][0] if i < n else geoms[0][0]

    # Row blocking: when the whole launch is only a few hundred programs, give
    # each program BR consecutive rows so the launch shrinks to a few dozen
    # programs (rows % BR == 0 is enforced, so no row bound is needed).  Large
    # planes keep BR = 1 and therefore the exact round-4 grid.
    progs = total_tiles * rows
    br = 1
    if progs <= 256:
        while br < 8 and rows % (br * 2) == 0 and progs // (br * 2) >= 32:
            br *= 2

    grid = (total_tiles, rows // br)
    kernel = _column_stack_kernel[grid](
        *args,
        BLOCK=block,
        NIN=n,
        CONV=conv,
        OD=od_tl,
        BR=br,
    )
    if reusable and grid[0] and rows and out.is_contiguous():
        try:
            dev = _tdriver.active.get_current_device()
            launch = _make_launch(kernel, grid, dev)
            ptrs = [t.data_ptr() for t in tensors]
            ptrs.append(out.data_ptr())
            sig = tuple((t.dtype, t.shape, t.stride()) for t in tensors)
        except Exception as exc:
            _LAST = None
            _INSTALL_ERROR = repr(exc)
        else:
            _INSTALL_ERROR = None
            # Preferred hot-path form: raw pointers.  The NPU launcher accepts
            # PyLong pointers directly, which skips a per-tensor data_ptr lookup
            # and aclrtPointerGetAttributes query and keeps the msprof tensor
            # shape probe from walking the argument list.  Used only when every
            # pointer is in the same 16-byte alignment class as at compile time.
            int_mode = _INT_PTRS and not (ptrs[0] & 15 or ptrs[-1] & 15)
            if int_mode:
                for i in range(n):
                    if ptrs[i] & 15:
                        int_mode = False
                        break
            targs = args + [block, n, conv, od_tl, br]
            if int_mode:
                targs[0] = ptrs[-1]
                for i in range(_NMAX):
                    targs[1 + i] = ptrs[i] if i < n else ptrs[0]
            _LAST = (
                n,
                sig,
                od,
                out.shape,
                out.device,
                targs,
                launch,
                tuple(ptrs),
                int_mode,
            )
    return out


def _launch_single(g, out_ptr, K, rows, block, conv, od_tl):
    tiles = triton.cdiv(g[2], block) if g[2] > 0 else 0
    if tiles == 0 or rows == 0:
        return 0
    _column_stack_kernel[(tiles, rows)](
        out_ptr,
        g[0],
        g[0],
        g[0],
        g[0],
        tiles,
        tiles,
        tiles,
        g[1],
        0,
        0,
        0,
        g[2],
        0,
        0,
        0,
        g[3],
        0,
        0,
        0,
        g[4],
        0,
        0,
        0,
        K,
        BLOCK=block,
        NIN=1,
        CONV=conv,
        OD=od_tl,
        BR=1,
    )
    return tiles


def column_stack_out(tensors, out=None, **kwargs):
    global _INT_PTRS, _LAST
    if out is None:
        out = kwargs.pop("out", None)
        if out is None:
            raise TypeError("run() missing required keyword-only argument: 'out'")
    if type(tensors) is torch.Tensor:
        tensors = (tensors,)
    elif not isinstance(tensors, (list, tuple)):
        tensors = list(tensors)

    plan = _LAST
    if plan is not None and len(tensors) == plan[0] and (plan[8] or _INT_PTRS):
        n, sig, od, oshape, odev, args, launch, ptrs, int_mode = plan
        if out.dtype is od and out.shape == oshape and out.device == odev:
            ok = True
            for i in range(n):
                t = tensors[i]
                d, sh, st = sig[i]
                if t.dtype is not d or t.shape != sh or t.stride() != st:
                    ok = False
                    break
            # Keep the compiled kernel's pointer-alignment specialization
            # valid: the plan was built from this same alignment class.
            if ok and int_mode:
                args[0] = out.data_ptr()
                if args[0] & 15 == ptrs[-1] & 15:
                    p0 = 0
                    for i in range(n):
                        p = tensors[i].data_ptr()
                        if p & 15 != ptrs[i] & 15:
                            ok = False
                            break
                        args[1 + i] = p
                        p0 = p
                    if ok:
                        for i in range(n, _NMAX):
                            args[1 + i] = p0
                        try:
                            launch(args)
                            return out
                        except Exception:
                            # e.g. an API-level msprof probe may require tensor
                            # objects; disable pointer mode and rebuild.
                            _INT_PTRS = False
                            _LAST = None
                            return _build(tensors, out)
            elif ok:
                args[0] = out
                if out.data_ptr() & 15 == ptrs[-1] & 15:
                    for i in range(n):
                        t = tensors[i]
                        if t.data_ptr() & 15 != ptrs[i] & 15:
                            ok = False
                            break
                        args[1 + i] = t
                    if ok:
                        for i in range(n, _NMAX):
                            args[1 + i] = tensors[0]
                        launch(args)
                        return out

    return _build(tensors, out)
